SELECT , c.name as category_name, u.nickname as author_name FROM article a LEFT JOIN category c ON a.category_id = c.id LEFT JOIN `user` u ON a.author_id = u.id
AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR a.summary LIKE CONCAT('%', #{keyword}, '%'))
AND a.category_id = #{categoryId}
AND a.status = #{status}
ORDER BY a.create_time DESC

